#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


REPO="${REPO:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"   # this checkout
LAPTOP_HOME="${LAPTOP_HOME:-$HOME/.warden-laptop}"   # the "laptop" side's own lease store
HOST_NAME="me"
LABEL_HOST="wizard-host"
LABEL_CLOUD="wizard-cloud"

# run "what" cmd… shows the command, asks y/N, runs it with live output. A failure
# or a "no" is recorded for the closing summary instead of ending the wizard.
run() {
  local desc="$1"; shift
  printf '  %s$%s %s\n' "$DIM" "$RESET" "$*"
  if confirm "Run: $desc?"; then
    if "$@"; then printf '  %s✓ %s%s\n' "$GREEN" "$desc" "$RESET"
    else warn "$desc failed (exit $?)"; SKIPPED+=("$desc: failed, see output above"); fi
  else
    SKIPPED+=("$desc: skipped")
  fi
}

# lw … runs warden as the "laptop": its own WARDEN_HOME, so it never shares
# leases with the "host" side (your normal ~/.warden) on this same Mac.
lw() { env WARDEN_HOME="$LAPTOP_HOME" warden "$@"; }

# other_terminal "cmd" puts a long-running command on the clipboard for a
# second terminal: Ctrl-C there must not kill this wizard.
other_terminal() {
  printf '\n    %s%s%s\n\n' "$BOLD" "$1" "$RESET"
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy; note "(copied to clipboard)"; fi
}

run_wizard() {

TOTAL_STAGES=13
ENV_FILE="$REPO/.env.wizard-remote-sims"   # gitignored (.env.*)
cd "$REPO"

banner "Remote sims: test it all locally"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Setup: install + link this checkout's warden"
say "Branch: $(git branch --show-current) @ $(git rev-parse --short HEAD)"
[[ -n "$(git status --porcelain)" ]] && warn "worktree has local changes"
run "bun install" bun install
say "The cloud stage (12) opens the desktop viewer. Linking with the viewer builds"
say "apps/viewer (Rust, a few minutes; needs @delacournz/apogee installed)."
if confirm "Link WITH the viewer (cli:link:viewer)?"; then
  run "link warden + viewer" bun run cli:link:viewer
else
  run "link warden" bun run cli:link
fi
note "warden now → $(command -v warden || echo 'not on PATH: add ~/.local/bin')"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Automated: TypeScript typecheck, lint, tests"
say "Includes the loopback sshd host tests and the remote driver tests."
run "typecheck" bun run typecheck
run "biome check" bun run check
run "all TS tests (a few min)" bun run test
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Automated: Rust (warden-rtc, warden-stream, viewer)"
run "cargo test warden-rtc" cargo test --manifest-path crates/warden-rtc/Cargo.toml
run "cargo test warden-stream (publisher → test peer, 60 fps)" cargo test --manifest-path crates/warden-stream/Cargo.toml
run "viewer TS tests" bun run --cwd apps/viewer test
run "viewer Rust tests" bun run --cwd apps/viewer test:rust
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Hosts: your Mac plays both laptop and host"
say "The 'laptop' uses its own warden home: $LAPTOP_HOME"
say "The 'host' is your normal warden (~/.warden), reached over a private sshd."
mkdir -p "$LAPTOP_HOME"
LAPTOP_KEY=$(lw host key 2>/dev/null | tail -n1 || true)
if [[ "$LAPTOP_KEY" != ssh-ed25519* ]]; then
  warn "couldn't read the laptop key (got: ${LAPTOP_KEY:-nothing})"
  ask LAPTOP_KEY "Run 'WARDEN_HOME=$LAPTOP_HOME warden host key' and paste the ssh-ed25519 line:"
fi
printf '  %s✓%s laptop key: %s…\n' "$GREEN" "$RESET" "${LAPTOP_KEY:0:40}"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Hosts: start the host side (second terminal)"
step "Open a SECOND terminal and run (it holds until Ctrl-C, max 2 h):"
other_terminal "warden host attach --grant '$LAPTOP_KEY' --as $HOST_NAME --for 2h"
step "It prints a line starting 'warden host add $HOST_NAME --ssh …--granted'. Copy that whole line."
while :; do
  ask HOST_ADD_LINE "Paste the 'warden host add …' line:"
  [[ "$HOST_ADD_LINE" == "warden host add "* ]] && break
  warn "that doesn't start with 'warden host add ', try again"
done
lw host rm "$HOST_NAME" >/dev/null 2>&1 || true   # re-runs: the port changes every attach
run "register the host on the laptop" env WARDEN_HOME="$LAPTOP_HOME" bash -c "$HOST_ADD_LINE"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Hosts: doctor + claim a sim on the host"
run "host doctor" lw host doctor "$HOST_NAME"
say "Claiming boots (or reuses) an iOS sim through the host's warden."
run "claim ios --host $HOST_NAME" lw claim ios --host "$HOST_NAME" --label "$LABEL_HOST" --ttl 30m
run "list host leases" lw ls --hosts
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Hosts: drive the host's sim with warden ui"
say "Every call crosses ssh to the host's driver. Watch the sim window move."
run "open Settings" lw ui open com.apple.Preferences
run "snapshot (interactive elements)" lw ui snapshot -i
step "Optional: try 'WARDEN_HOME=$LAPTOP_HOME warden ui press <ref>' from the snapshot."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Hosts: watch + drive it in the browser (warden view)"
step "In a THIRD terminal run this. It opens a browser tab:"
other_terminal "WARDEN_HOME=$LAPTOP_HOME warden view"
step "Click = tap, drag = swipe, typing types, Esc = home. Portrait only."
step "Ctrl-C in that terminal when done (the lease stays yours)."
pause "Done with the browser view? Press Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Hosts: dev client on the host, Metro here (optional)"
say "Builds the example app's dev client on first run (can take 10+ min)."
if confirm "Try warden dev --host with apps/example?"; then
  step "In a THIRD terminal (stop 'warden view' first) run:"
  other_terminal "cd $REPO/apps/example && WARDEN_HOME=$LAPTOP_HOME warden dev ios --host $HOST_NAME"
  step "Wait for the app on the host's sim, edit a screen in apps/example, watch it refresh."
  step "Ctrl-C there when done."
  pause "Done with dev --host? Press Enter"
else
  SKIPPED+=("dev --host: skipped")
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Hosts: release + stop the host"
run "release the host leases" lw release --mine --label "$LABEL_HOST"
step "In the SECOND terminal (warden host attach), press Ctrl-C to stop the private sshd."
pause "Stopped it? Press Enter"
if confirm "Remove the '$HOST_NAME' host record from the laptop home?"; then
  run "host rm $HOST_NAME" lw host rm "$HOST_NAME"
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Cloud: log in to warden cloud"
say "Hosted Revyl devices. Use a named account so your default stays untouched."
note "Prod: https://api.warden.co.nz (viewer input routes may 404 if the API lacks them)."
ask CLOUD_API_URL "API URL [https://api.warden.co.nz]:"
CLOUD_API_URL="${CLOUD_API_URL:-https://api.warden.co.nz}"
write_env CLOUD_API_URL "$CLOUD_API_URL"
ask CLOUD_ACCOUNT "warden account name for this test [wizard]:"
CLOUD_ACCOUNT="${CLOUD_ACCOUNT:-wizard}"
write_env CLOUD_ACCOUNT "$CLOUD_ACCOUNT"
step "Login opens your browser: approve the code there."
run "warden login" warden login --account "$CLOUD_ACCOUNT" --api-url "$CLOUD_API_URL"
run "whoami (balance, Revyl approval)" env WARDEN_ACCOUNT="$CLOUD_ACCOUNT" warden whoami
note "If it says 'approve in Revyl with code …', open that link and approve before stage 12."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Cloud: hosted device in the desktop viewer"
warn "This spends real credit: \$0.20 per device-minute, billed from boot to stop."
if confirm "Claim a hosted iOS device and open the viewer?"; then
  step "The viewer window opens on the device. Tap, drag, type, rotate, screenshot."
  step "Close the window and pick 'Shut down' to stop billing, then come back here."
  run "claim --remote --view" env WARDEN_ACCOUNT="$CLOUD_ACCOUNT" warden claim ios --remote --view --label "$LABEL_CLOUD"
  run "release any wizard cloud lease left" env WARDEN_ACCOUNT="$CLOUD_ACCOUNT" warden release --mine --label "$LABEL_CLOUD"
  run "billing (see the usage line)" env WARDEN_ACCOUNT="$CLOUD_ACCOUNT" warden billing --limit 5
else
  SKIPPED+=("cloud device + viewer: skipped")
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Streams: live bench of the WebRTC publisher"
say "Publisher + test peer in one process, fed the 60 fps fixture for 10 s."
say "Prints one JSON summary: connect time, fps, latency."
run "live bench on the fixture" cargo run --release --manifest-path crates/warden-stream/Cargo.toml \
  --example live -- --au-file "$REPO/crates/warden-stream/tests/fixtures/fixture.h264" --loop --seconds 10
note "Against a real sim: --au-socket <helper socket> --helper-stdin <fifo> (crates/warden-stream/AGENTS.md)."
pause

finish
note "Laptop-side warden home: $LAPTOP_HOME (rm -rf it to reset)."
note "Back to your normal warden: bun run cli:unlink"
}

run_wizard "$@"; exit
